"""Closes the loop: traffic generated by the live tests -> Keycloak ECS logs ->
Pipeline C -> detection -> findings. Requires the backend (BACKEND_URL)."""
from __future__ import annotations

import os

import pytest
import requests

pytestmark = pytest.mark.live
BACKEND = os.environ.get("BACKEND_URL", "http://localhost:8000")


@pytest.fixture(scope="module")
def backend():
    try:
        requests.get(f"{BACKEND}/api/health", timeout=5).raise_for_status()
    except requests.RequestException:
        pytest.skip(f"backend not reachable at {BACKEND}")
    requests.post(f"{BACKEND}/api/ingest/all", timeout=300).raise_for_status()
    return BACKEND


def test_runtime_logs_are_ingested_with_anonymous_rule(backend):
    s = requests.get(f"{backend}/api/logs/summary", params={"origin": "keycloak-runtime"}, timeout=30).json()
    if s["records"] == 0:
        pytest.skip("no runtime logs yet: run the live scenario tests first")
    assert s["anonymous"] > 0
    assert set(s["by_origin"]) == {"keycloak-runtime"}


def test_detection_on_runtime_evidence(backend):
    a = requests.post(f"{backend}/api/assessments", timeout=120, json={
        "source_version": os.environ.get("KC_SOURCE_VERSION", "26.5.0"),
        "target_version": os.environ.get("KC_TARGET_VERSION", "26.6.3"),
        "log_origins": ["keycloak-runtime"], "label": "live-runtime"}).json()
    findings = requests.get(f"{backend}/api/assessments/{a['assessment_id']}/findings", timeout=30).json()
    keys = {(f["bc_id"], f["client_id"]) for f in findings}
    assert ("KC-BC-001", "legacy-portal") in keys
    control = [f for f in findings if f["bc_id"] == "KC-BC-005"]
    assert control and control[0]["client_identified"] is False
    for f in findings:
        for ev in f["evidence"]:
            if ev.get("type") == "runtime":
                assert ev["origin"] == "keycloak-runtime"  # synthetic logs never presented as server evidence
